        public Builder cancelledAt(@Nullable OffsetDateTime cancelledAt) {
            this.cancelledAt = cancelledAt;
            return this;
        }

        /**
         * number of children
         */
        public Builder children(@Nullable Double children) {
            this.children = children;
            return this;
        }

        /**
         * the booking channel confirmation code
         */
        public Builder confirmationCode(@Nullable String confirmationCode) {
            this.confirmationCode = confirmationCode;
            return this;
        }

        /**
         * when the reservation was created (ISO-8601 / YYYY-MM-DDTHH:MM:SSZ format)
         */
        public Builder createdAt(@Nullable OffsetDateTime createdAt) {
            this.createdAt = createdAt;
            return this;
        }

